<script setup lang="ts">
import { nextTick, reactive, ref, watch } from 'vue'
import { request } from '../api/client'
import type { RecordData } from '../types'
import { kinds } from '../lib/display'
import { useRouter } from 'vue-router'
import { state, createProject, createWorkflow } from '../store/workbench'
const router=useRouter(), projectDialog=ref<HTMLDialogElement>(), workflowDialog=ref<HTMLDialogElement>()
const project=reactive({name:'',description:'',actor:''}), workflow=reactive({title:'通用业务验证流程',goal:'逐步审阅需求、架构和实现，并核对真实参考测试证据。',actor:''})
const projectError=ref(''), workflowError=ref('')
watch(()=>state.showProject,async value=>{ await nextTick(); if(value) { project.actor=state.actor; projectError.value=''; projectDialog.value?.showModal() } else projectDialog.value?.close() })
watch(()=>state.showWorkflow,async value=>{ await nextTick(); if(value) { workflow.actor=state.actor; workflowError.value=''; workflowDialog.value?.showModal() } else workflowDialog.value?.close() })

const mode=ref('generic_v1'),executor=ref('manual'),release=ref('v1'),catalog=ref<RecordData>({entities:[],keys:{}})
const slots:Record<string,string>={requirement:'Requirement',architecture:'ArchitectureComponent',interface:'Interface',data:'DataModel',code:'CodeArtifact',test:'TestCase'}
const selected=reactive<Record<string,string[]>>({requirement:[],architecture:[],interface:[],data:[],code:[],test:[]}),rules=ref<string[]>([])
function defaults(){
  const reqKeys=['REQ-ENROLL',...(release.value!=='v1'?['REQ-CAPACITY']:[]),...(release.value==='v1.2'?['REQ-TIME-CONFLICT']:[])]
  const ruleKeys=['BR-UNIQUE',...(release.value!=='v1'?['BR-CAPACITY']:[]),...(release.value==='v1.2'?['BR-TIME-CONFLICT']:[])]
  for(const [slot,kind] of Object.entries(slots))selected[slot]=catalog.value.entities.filter((e:RecordData)=>e.kind===kind&&e.status!=='archived'&&(executor.value!=='course_selection_v1'||slot!=='requirement'||reqKeys.includes(catalog.value.keys[e.id]))&&(slot!=='test'||executor.value!=='course_selection_v1'||catalog.value.keys[e.id]==='TEST-ENROLL')).map((e:RecordData)=>e.id)
  rules.value=catalog.value.entities.filter((e:RecordData)=>e.kind==='BusinessRule'&&(executor.value!=='course_selection_v1'||ruleKeys.includes(catalog.value.keys[e.id]))).map((e:RecordData)=>e.id)
}
watch([executor,release],defaults)
watch(()=>state.showWorkflow,async value=>{if(value){try{catalog.value=await request(`/workbench/projects/${state.projectId}/knowledge`);defaults()}catch(e){workflowError.value=(e as Error).message}}})
function options(){if(mode.value==='order_cancellation_v1')return {scenario:mode.value};const ref=(id:string)=>{const e=catalog.value.entities.find((e:RecordData)=>e.id===id);return {id,version:e.version}};return {scenario:'generic_v1',executor:executor.value,release:release.value,bindings:Object.fromEntries(Object.entries(selected).map(([key,ids])=>[key,ids.map(ref)])),input_knowledge:rules.value.map(ref)}}

function closeProject(event?:Event) { if(state.busy){event?.preventDefault();return} state.showProject=false }
function closeWorkflow(event?:Event) { if(state.busy){event?.preventDefault();return} state.showWorkflow=false }
async function submitProject() { if(state.busy)return; projectError.value=''; try { await createProject(project.name.trim(),project.description.trim(),project.actor.trim()); project.name='';project.description=''; await router.push('/projects') } catch(error){projectError.value=(error as Error).message} }
async function submitWorkflow() { if(state.busy)return; workflowError.value=''; try { const created=await createWorkflow(workflow.title.trim(),workflow.goal.trim(),workflow.actor.trim(),options()); await router.push(`/workflows/${created.id}/overview`) } catch(error){workflowError.value=(error as Error).message} }
</script>
<template><dialog ref="projectDialog" class="form-dialog" @cancel="closeProject"><form @submit.prevent="submitProject"><div class="dialog-heading"><div><p class="eyebrow">创建项目</p><h2>创建验证项目</h2></div><button class="icon-button" type="button" :disabled="state.busy" aria-label="关闭" @click="closeProject()">×</button></div><p class="dialog-description">为本地验证建立清晰的知识边界。不会连接或修改业务仓库。</p><label class="field">项目名称<input v-model="project.name" required maxlength="200" placeholder="例如：工程协作验证" :disabled="state.busy"></label><label class="field">项目说明<textarea v-model="project.description" rows="3" maxlength="4000" placeholder="记录本次验证的目的（可选）" :disabled="state.busy"></textarea></label><label class="field">操作署名<input v-model="project.actor" required maxlength="100" autocomplete="name" placeholder="请输入你的姓名或本地署名" :disabled="state.busy"><small>用于记录谁创建了项目，不代表已完成身份认证。</small></label><p v-if="projectError" class="form-error" role="alert">{{ projectError }}</p><div class="dialog-footer"><button class="button secondary" type="button" :disabled="state.busy" @click="closeProject()">取消</button><button class="button primary" type="submit" :disabled="state.busy || !project.name.trim() || !project.actor.trim()">{{ state.busy ? '创建中…' : '创建项目' }}</button></div></form></dialog><dialog ref="workflowDialog" class="form-dialog" @cancel="closeWorkflow"><form @submit.prevent="submitWorkflow"><div class="dialog-heading"><div><p class="eyebrow">创建验证流程</p><h2>新建验证流程</h2></div><button class="icon-button" type="button" :disabled="state.busy" aria-label="关闭" @click="closeWorkflow()">×</button></div><label class="field">流程模式<select v-model="mode"><option value="generic_v1">通用流程：绑定已有知识</option><option value="order_cancellation_v1">订单取消参考流程</option></select></label>
<template v-if="mode==='generic_v1'"><label class="field">执行方式<select v-model="executor"><option value="manual">人工提交（尚未配置可信代码执行器）</option><option value="course_selection_v1">选课教学适配器</option></select></label><label v-if="executor==='course_selection_v1'" class="field">教学版本<select v-model="release"><option>v1</option><option>v1.1</option><option>v1.2</option></select></label><p>选择本轮已确认的知识版本。下方可多选，已有身份将被复用；创建不会自动批准产物。</p>
<label v-for="(kind,slot) in slots" :key="slot" class="field">绑定{{ kinds[kind] }}<select v-model="selected[slot]" multiple class="binding-select" required><option v-for="e in catalog.entities.filter((e:RecordData)=>e.kind===kind && e.status!=='archived')" :key="e.id" :value="e.id">{{ e.name }} · v{{ e.version }}</option></select></label><label class="field">额外业务规则（固定版本）<select v-model="rules" multiple class="binding-select"><option v-for="e in catalog.entities.filter((e:RecordData)=>e.kind==='BusinessRule')" :key="e.id" :value="e.id">{{ e.name }} · v{{ e.version }}</option></select></label><p v-if="!catalog.entities.some((e:RecordData)=>e.kind==='Requirement')" class="info-box warning">尚无需求。请先在“项目知识”新建或导入，再确认提案。</p></template><label class="field">流程名称<input v-model="workflow.title" required maxlength="200" :disabled="state.busy"></label><label class="field">验证目标<textarea v-model="workflow.goal" required rows="3" maxlength="4000" :disabled="state.busy"></textarea><small>目标记录本轮验证意图；产物由所选适配器或人工提交，尚未接入大模型。</small></label><label class="field">操作署名<input v-model="workflow.actor" required maxlength="100" autocomplete="name" placeholder="请输入你的姓名或本地署名" :disabled="state.busy"></label><p v-if="workflowError" class="form-error" role="alert">{{ workflowError }}</p><div class="dialog-footer"><button class="button secondary" type="button" :disabled="state.busy" @click="closeWorkflow()">取消</button><button class="button primary" type="submit" :disabled="state.busy || !workflow.title.trim() || !workflow.goal.trim() || !workflow.actor.trim()">{{ state.busy ? '创建中…' : '创建草稿流程' }}</button></div></form></dialog></template>
